"""Islamiat (Ikhtiari) XII PDF74: pp.138–139 — ahadith 44, 45. Run: python class12_iski_page074.py"""
from class12_iski_common import BOOK, Builder, rec, P, AR


def p74():
    b = Builder()
    b.h('Hadith no. 44', 'حدیث نمبر 44', 'حدیث نمبر ۴۴')
    AR(b, 'عَنِ النُّعْمَانِ بْنِ بَشِيْرٍ رَضِيَ اللّٰهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ تَرَى الْمُؤْمِنِيْنَ فِيْ تَرَاحُمِهِمْ وَتَوَادِّهِمْ وَتَعَاطُفِهِمْ كَمَثَلِ الْجَسَدِ اِذَا اشْتَكٰى عُضْوٌ، تَدَاعٰى لَهٗ سَآئِرُ جَسَدِهٖ بِالسَّهَرِ وَالْحُمّٰى', 'صحیح مسلم و صحیح البخاری')
    b.p('Translation: Hazrat Nu\'man bin Bashir (may Allah be pleased with him) says that the Messenger of Allah ﷺ said that the believers, in showing mercy to one another, in loving and in being gentle, are like one body. When one limb is in pain, the whole body becomes afflicted with fever and sleeplessness.', 'ترجمہ: حضرت نعمان بن بشیر رضی اللہ عنہ فرماتے ہیں رسول اللہ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا کہ مومنین ایک دوسرے پر رحم کرنے میں، محبت کرنے میں اور نرمی کرنے میں ایک جسم کی مانند ہیں۔ جب ایک عضو کو تکلیف ہوتی ہے تو سارا جسم بخار اور بے خوابی میں مبتلا ہو جاتا ہے۔', 'ژباړه: حضرت نعمان بن بشیر رضي الله عنه وايي چې د الله رسول ﷺ وفرمایل: مؤمنان په یو بل باندې په رحم کولو، مینه کولو او نرمۍ کې د یوه بدن په څېر دي. کله چې یو غړی درد ولري، ټول بدن په تبه او بې‌خوبۍ اخته کېږي.')
    b.h('Explanation', 'تشریح', 'تشریح')
    P(b, [('In this blessed hadith the mutual brotherhood and love of Muslims is mentioned. The Noble Prophet ﷺ made an imperishable and unparalleled display of brotherhood on the occasion of the Hijrah to Madinah by establishing it between the Muhajirin and the Ansar. That example has become a living, eternal reality of the Mustafavi society established by him ﷺ. Although in the present age Muslims are victims of mutual hatreds and conflicts, this too is a reality that in times of calamity those who recite the kalimah of the Noble Prophet ﷺ rise up to help their brothers. In our dear homeland its clear example came forth through the expression of one-ness and practical help with those made homeless by earthquake and flood.', 'اس حدیثِ مبارکہ میں مسلمانوں کی باہمی اخوت و محبت کا ذکر ہے۔ نبی کریم صلی اللہ علیہ وآلہٖ وسلم نے اخوت کا لازوال اور بے مثال مظاہرہ ہجرتِ مدینہ کے موقع پر مہاجرین اور انصار کے درمیان قائم کر کے فرمایا تھا۔ وہ مثال آپ صلی اللہ علیہ وآلہٖ وسلم کے قائم کردہ مصطفوی معاشرے کی زندہ جاوید حقیقت بن چکی ہے۔ اگرچہ موجودہ دور میں مسلمان باہمی نفرتوں اور چپقلشوں کا شکار ہیں لیکن یہ بھی حقیقت ہے کہ مصیبت کی گھڑیوں میں نبی کریم صلی اللہ علیہ وآلہٖ وسلم کا کلمہ پڑھنے والے اپنے بھائیوں کی مدد کے لیے اٹھ کھڑے ہوتے ہیں۔ وطنِ عزیز میں اس کی واضح مثال زلزلے، سیلاب میں بے گھر ہونے والے افراد کے ساتھ اظہارِ یکجہتی اور عملی مدد کے ذریعے سامنے آئی ہے۔', 'په دې مبارک حدیث کې د مسلمانانو د متقابلې ورورولۍ او مینې یادونه ده. نبي کریم ﷺ د ورورولۍ نه زوالېدونکې او بې‌سارې بېلګه د مدینې ته د هجرت پر مهال د مهاجرینو او انصارو ترمنځ په جوړولو ښکاره کړه. هغه بېلګه د هغه ﷺ د جوړې کړې مصطفوي ټولنې تل ژوندی حقیقت ګرځېدلې. که څه هم په اوسنۍ دوره کې مسلمانان د متقابلو کرکو او شخړو ښکار دي، خو دا هم حقیقت دی چې د مصیبت په شېبو کې د نبي کریم ﷺ کلمه ویونکي د خپلو وروڼو د مرستې لپاره راپاڅېږي. په ګران هېواد کې د دې ښکاره بېلګه د زلزلې او سېلاب له امله له بې‌کوره شویو کسانو سره د یووالي په څرګندولو او عملي مرستې کې راڅرګنده شوه.'),
          ('His ﷺ saying is true even today, that believers in mercy, love and kindness are like one body. Just as when one part of the body becomes ill the whole body becomes restless, in the same way if the Muslims of some one place are distressed, then the whole Muslim Ummah becomes restless.', 'آپ صلی اللہ علیہ وآلہٖ وسلم کا ارشاد آج بھی سچ ہے کہ مومن رحمت، محبت اور شفقت میں ایک جسم کی مانند ہیں۔ جس طرح جسم کا ایک حصہ بیمار ہو جائے تو پورا جسم بے قرار ہو جاتا ہے اسی طرح اگر کسی ایک جگہ کے مسلمان پریشان حال ہوں تو ساری امتِ مسلمہ بے قرار ہو جاتی ہے۔', 'د هغه ﷺ ارشاد نن هم رښتیا دی چې مؤمنان په رحمت، مینه او شفقت کې د یوه بدن په څېر دي. لکه څنګه چې د بدن یوه برخه ناروغه شي نو ټول بدن بې‌قراره کېږي، همداسې که د کوم یو ځای مسلمانان پرېشانه وي، ټول اسلامي امت بې‌قراره کېږي.'),
          ('We should live as one soul in mutual affairs. If another Muslim brother needs our help, we should help at once. This is real brotherhood and true fraternity.', 'ہمیں چاہیے کہ ہم باہمی معاملات میں یک جان ہو کر رہیں۔ اگر کسی دوسرے مسلمان بھائی کو ہماری مدد کی ضرورت پڑے تو فوراً مدد کریں۔ یہی اخوت اور اصل بھائی چارہ ہے۔', 'موږ باید په متقابلو چارو کې یو روح شو. که بل مسلمان ورور زموږ مرستې ته اړتیا ولري، سمدستي مرسته یې وکړو. همدا ورورولي او اصلي وروري ده.')])
    r1 = rec(b, 2, 138, 74, [138])
    t = Builder()
    t.h('Hadith no. 45', 'حدیث نمبر 45', 'حدیث نمبر ۴۵')
    AR(t, 'عَنْ اَبِيْ هُرَيْرَةَ اَنَّ رَسُوْلَ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ قَالَ: بَيْنَمَا رَجُلٌ يَّمْشِيْ بِطَرِيْقٍ، اشْتَدَّ عَلَيْهِ الْعَطَشُ، فَوَجَدَ بِئْرًا فَنَزَلَ فِيْهَا، فَشَرِبَ ثُمَّ خَرَجَ، فَاِذَا كَلْبٌ يَّلْهَثُ يَاْكُلُ الثَّرٰى مِنَ الْعَطَشِ، فَقَالَ الرَّجُلُ: لَقَدْ بَلَغَ هٰذَا الْكَلْبَ مِنَ الْعَطَشِ مِثْلُ الَّذِيْ كَانَ بَلَغَ بِيْ، فَنَزَلَ الْبِئْرَ فَمَلَاَ خُفَّهٗ، ثُمَّ اَمْسَكَهٗ بِفِيْهِ، فَسَقَى الْكَلْبَ فَشَكَرَ اللّٰهُ لَهٗ، فَغَفَرَ لَهٗ، قَالُوْا: يَا رَسُوْلَ اللّٰهِ، وَاِنَّ لَنَا فِي الْبَهَآئِمِ اَجْرًا؟ فَقَالَ: فِيْ كُلِّ ذَاتِ كَبِدٍ رَطْبَةٍ اَجْرٌ', 'صحیح البخاری')
    t.p('Translation: It is narrated from Hazrat Abu Hurayrah (may Allah be pleased with him) that the Messenger of Allah ﷺ said: While a man was walking on a road, he felt intense thirst. He found a well, went down into it, drank water and came out. Suddenly he saw a dog which was panting and, from the intensity of thirst, licking the moist earth. The man said in his heart: this dog has suffered the same pain of thirst which had reached me. So he went down into the well, filled his leather sock with water, held it in his mouth, brought it out, and gave the dog water to drink. So Allah the Exalted looked at this deed of his with appreciation and forgave him. The noble Companions (may Allah be pleased with them) asked: O Messenger of Allah! Is there reward for us even in (sympathy with) animals? He ﷺ said: in (serving) every living creature with a moist liver there is reward and recompense.', 'ترجمہ: حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا! اس دوران کہ ایک آدمی راستے پر چل رہا تھا، کہ اسے سخت پیاس لگی، اس کو ایک کنواں ملا، اس میں اترا اور پانی پی کر نکل آیا۔ اچانک اس نے ایک کتے کو دیکھا جو ہانپ رہا تھا اور پیاس کی شدت سے تر مٹی چاٹ رہا تھا، تو آدمی نے دل میں کہا اس کتے کو پیاس کی وہ تکلیف پہنچی ہے۔ جو مجھے پہنچی تھی چنانچہ وہ کنویں میں اترا اور اپنا موزہ پانی سے بھر کر اپنے منہ سے پکڑا اور باہر لا کر کتے کو پانی پلایا۔ پس اللہ تعالیٰ نے اس کے اس عمل کو قدر کی نگاہ سے دیکھا اور اس کی مغفرت کی۔ صحابہ کرام رضی اللہ عنہم نے پوچھا۔ اللہ کے رسول! کیا ہمارے لیے جانوروں (سے ہمدردی) میں بھی اجر ہے تو آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا! ہر تر جگر والے میں اجر و ثواب ہے۔', 'ژباړه: له حضرت ابوهریره رضي الله عنه روایت دی چې د الله رسول ﷺ وفرمایل: یو سړی پر لاره روان و چې سخته تنده یې شوه. یوه کوهی یې وموند، په کې ښکته شو، اوبه یې وڅښلې او راووت. ناڅاپه یې یو سپی ولید چې ساه یې لنډه وه او د تندې له شدته یې لنده خاوره څټله. سړي په زړه کې وویل: دې سپي ته د تندې هماغه تکلیف رسېدلی چې ماته رسېدلی و. نو کوهي ته ښکته شو، خپل موزه یې له اوبو ډک کړ، په خوله یې ونیوه، راوویست او سپي ته یې اوبه ورکړې. نو الله تعالی د هغه دا عمل په قدر وکاته او ویې باښه. صحابه کرامو رضي الله عنهم وپوښتل: اې د الله رسوله! ایا موږ ته د څارویو (سره په همدردۍ) کې هم اجر شته؟ هغه ﷺ وفرمایل: د هر لوند ځیګر لرونکي (ژوندي) په خدمت کې اجر او ثواب دی.')
    BOOK.save(74, [(2, r1), (2, rec(t, 2, 139, 74, [139]))], issues=[{'id': 'iski12-pdf074', 'unit': 2, 'printedPage': 138,
               'description': 'Hadith 44 Arabic on p.138 is smudged in the middle ("قَالَ رَسُوْلُ" and "وَتَعَاطُفِهِمْ كَمَثَلِ" partly blank in the print); restored from the standard text of this well-known hadith. Hadith 45 Arabic end of line 1 ("يَمْشِيْ") is faded at the edge — read through. Student marks excluded.'}])


if __name__ == '__main__':
    p74()
